//! Quadrature measures: twin of the `volume` and `quantile` requests of `tsEngine.ts` (cell-centre grid or the R3 low-discrepancy sequence,
//! hard threshold per sample). Points are generated by index and reduced in fixed chunks, so no point array is ever materialised for a volume.

use crate::eval::Evaluator;
use crate::sampling::Grid;
use llull_jsmath::pow;
use rayon::prelude::*;

const PHI3: f64 = 1.220_744_084_605_759_6;
const CHUNK: u64 = 1 << 15;

pub struct VolumeMeasure {
    pub volume: f64,
    pub region_volume: f64,
    pub samples: u64,
    pub non_finite: u64,
}

struct Points {
    grid: Grid,
    extent: [f64; 3],
    alpha: [f64; 3],
    low_discrepancy: bool,
}

impl Points {
    fn new(grid: &Grid, low_discrepancy: bool) -> Points {
        Points {
            grid: *grid,
            extent: [0, 1, 2].map(|a| grid.max[a] - grid.min[a]),
            alpha: [1.0 / PHI3, 1.0 / pow(PHI3, 2.0), 1.0 / pow(PHI3, 3.0)],
            low_discrepancy,
        }
    }

    fn at(&self, n: u64) -> [f64; 3] {
        let g = &self.grid;
        if self.low_discrepancy {
            return [0, 1, 2].map(|a| g.min[a] + ((0.5 + (n as f64 + 1.0) * self.alpha[a]) % 1.0) * self.extent[a]);
        }
        let c = g.cells;
        let ijk = [(n % c[0] as u64) as f64, ((n / c[0] as u64) % c[1] as u64) as f64, (n / (c[0] as u64 * c[1] as u64)) as f64];
        [0, 1, 2].map(|a| g.min[a] + ((ijk[a] + 0.5) * self.extent[a]) / c[a] as f64)
    }
}

/// Volume of {f <= 0} (clipped to {region <= 0}) over the grid box, each cell counting whole by its sample.
pub fn volume(main: &Evaluator, region: Option<&Evaluator>, grid: &Grid, low_discrepancy: bool) -> VolumeMeasure {
    let points = Points::new(grid, low_discrepancy);
    let count = grid.cell_count();
    let chunks = count.div_ceil(CHUNK);
    let (solid, in_region, non_finite) = (0..chunks)
        .into_par_iter()
        .map_init(
            || (vec![0.0; main.instrs.len()], vec![0.0; region.map_or(0, |r| r.instrs.len())]),
            |(regs, region_regs), chunk| {
                let (mut solid, mut in_region, mut non_finite) = (0u64, 0u64, 0u64);
                for n in chunk * CHUNK..((chunk + 1) * CHUNK).min(count) {
                    let [x, y, z] = points.at(n);
                    let value = main.value_at(regs, x, y, z);
                    non_finite += u64::from(!value.is_finite());
                    let clip = region.map(|r| r.value_at(region_regs, x, y, z));
                    if let Some(c) = clip {
                        non_finite += u64::from(!c.is_finite());
                        if c.is_nan() || c > 0.0 {
                            continue;
                        }
                    }
                    in_region += 1;
                    solid += u64::from(value <= 0.0);
                }
                (solid, in_region, non_finite)
            },
        )
        .reduce(|| (0, 0, 0), |a, b| (a.0 + b.0, a.1 + b.1, a.2 + b.2));
    let box_volume = (grid.max[0] - grid.min[0]) * (grid.max[1] - grid.min[1]) * (grid.max[2] - grid.min[2]);
    let unit = if count == 0 { 0.0 } else { box_volume / count as f64 };
    VolumeMeasure { volume: solid as f64 * unit, region_volume: in_region as f64 * unit, samples: count, non_finite }
}

/// Sorted-sample quantiles of f (or |f|) over the midpoint grid; NaN samples are dropped. Empty input answers NaN.
pub fn quantiles(main: &Evaluator, grid: &Grid, probabilities: &[f64], absolute: bool) -> Vec<f64> {
    let points = Points::new(grid, false);
    let count = grid.cell_count();
    let mut values: Vec<f64> = (0..count as usize)
        .into_par_iter()
        .with_min_len(CHUNK as usize)
        .map_init(
            || vec![0.0; main.instrs.len()],
            |regs, n| {
                let [x, y, z] = points.at(n as u64);
                let v = main.value_at(regs, x, y, z);
                if absolute {
                    v.abs()
                } else {
                    v
                }
            },
        )
        .filter(|v| !v.is_nan())
        .collect();
    values.par_sort_unstable_by(f64::total_cmp);
    probabilities
        .iter()
        .map(|&p| {
            if values.is_empty() {
                return f64::NAN;
            }
            let index = (p * values.len() as f64).floor().max(0.0);
            values[(index as usize).min(values.len() - 1)]
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tape::{Instr, Op, SLOTS};

    /// f = x - 1 (a half space): material where x <= 1.
    fn plane() -> Evaluator {
        Evaluator {
            instrs: vec![
                Instr { op: Op::X, args: [-1; SLOTS] },
                Instr { op: Op::Const, args: [0, -1, -1, -1, -1] },
                Instr { op: Op::Sub, args: [0, 1, -1, -1, -1] },
            ],
            output: 2,
            constants: vec![1.0],
            meshes: vec![],
            struts: vec![],
            sampled: vec![],
        }
    }

    #[test]
    fn midpoint_and_low_discrepancy_volumes_of_a_half_space() {
        let grid = Grid::new([0.0; 3], [4.0, 2.0, 2.0], 0.5).unwrap();
        let m = volume(&plane(), None, &grid, false);
        assert_eq!((m.volume, m.region_volume, m.samples, m.non_finite), (4.0, 16.0, 8 * 4 * 4, 0));
        let q = volume(&plane(), None, &grid, true);
        assert!((q.volume - 4.0).abs() < 1.5, "low-discrepancy estimate {}", q.volume);
        assert_eq!(q.samples, 128);
    }

    #[test]
    fn a_region_clips_the_solid_and_counts_its_own_volume() {
        let region = plane();
        let grid = Grid::new([0.0; 3], [4.0, 2.0, 2.0], 0.5).unwrap();
        let m = volume(&plane(), Some(&region), &grid, false);
        assert_eq!((m.volume, m.region_volume), (4.0, 4.0));
    }

    #[test]
    fn quantiles_pick_sorted_samples_and_drop_nan() {
        let grid = Grid::new([0.0; 3], [4.0, 1.0, 1.0], 1.0).unwrap();
        // x - 1 at x = 0.5, 1.5, 2.5, 3.5 is -0.5, 0.5, 1.5, 2.5
        assert_eq!(quantiles(&plane(), &grid, &[0.0, 0.5, 0.99, 2.0, -1.0], false), vec![-0.5, 1.5, 2.5, 2.5, -0.5]);
        assert_eq!(quantiles(&plane(), &grid, &[0.0, 0.25], true), vec![0.5, 0.5]);
        let mut nan = plane();
        nan.instrs[2] = Instr { op: Op::Sqrt, args: [1, -1, -1, -1, -1] };
        nan.constants = vec![-1.0];
        assert!(quantiles(&nan, &grid, &[0.5], false)[0].is_nan(), "every sample is NaN");
    }
}
